(228, 1, '2019-03-10 02:34:16', '2019-03-09 23:34:16', '<div itemscope=\"\" itemtype=\"http://schema.org/Organization\">\r\n<p style=\"text-align:justify\"><span style=\"font-size:20px;\"><span style=\"font-family:times new roman,times,serif;\">Компания:</span></span> <em><span style=\"font-size:20px;\"><span itemprop=\"name\" style=\"font-family:times new roman,times,serif;\">AnSee</span></span></em></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:20px\"><span style=\"font-family:times new roman,times,serif\">Позвоните нам:<em><span itemprop=\"telephone\"> 8 (499) 350-44-61</span></em></span></span></p>\r\n\r\n<div itemprop=\"address\" itemscope=\"\" itemtype=\"http://schema.org/PostalAddress\">\r\n<p style=\"text-align:justify\"><font face=\"times new roman, times, serif\"><span style=\"font-size: 20px; line-height: 32px;\"><i>Адрес:</i></span></font></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:20px\"><span itemprop=\"addressLocality\" style=\"font-family:times new roman,times,serif\">Город:&nbsp;<em>Москва</em></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:20px\"><span style=\"font-family:times new roman,times,serif\">Наш главный офис:&nbsp;<em><span itemprop=\"streetAddress\">Краснопресненская набережная, д.12</span></em></span></span></p>\r\n</div>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:20px\"><span style=\"font-family:times new roman,times,serif\">Напишите: <img alt=\"почта\" src=\"/wp-content/uploads/2019/03/mail_3.png\" style=\"height:30px; margin-left:2px; margin-right:2px; width:30px\" title=\"почта\">&nbsp;<span itemprop=\"email\" span=\"\">compprofimaster@yahoo.com<noscript>compprofimaster@yahoo.com</noscript></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:20px\"><span style=\"font-family:times new roman,times,serif\">Время работы: <em>с 9:00 до 22:00</em></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\"><span style=\"font-family:times new roman,times,serif\">Для связи с нами вы также можете заказать обратный звонок.</span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\"><span style=\"font-family:times new roman,times,serif\"><em>Главный офис на карте</em></span></span></p>\r\n</div>\r\n<!-- Этот блок кода нужно вставить в ту часть страницы, где вы хотите разместить карту (конец) -->﻿<ymaps id=\"ymaps1552154061866756924\" style=\"display: block; width: 800px; height: 450px;\"><ymaps class=\"ymaps-2-1-73-map\" style=\"width: 800px; height: 450px;\"><ymaps class=\"ymaps-2-1-73-map ymaps-2-1-73-i-ua_js_yes ymaps-2-1-73-map-bg ymaps-2-1-73-islets_map-lang-ru\" style=\"width: 800px; height: 450px;\"><ymaps class=\"ymaps-2-1-73-inner-panes\"><ymaps class=\"ymaps-2-1-73-events-pane ymaps-2-1-73-user-selection-none\" unselectable=\"on\" style=\"height: 100%; width: 100%; top: 0px; left: 0px; position: absolute; z-index: 3500; cursor: pointer;\"></ymaps><ymaps class=\"ymaps-2-1-73-ground-pane\" style=\"top: 0px; left: 0px; position: absolute; transform: translate3d(0px, 0px, 0px) scale(1, 1); z-index: 701;\"><ymaps style=\"z-index: 150; position: absolute;\"><canvas height=\"1412\" width=\"2112\" style=\"position: absolute; width: 1056px; height: 706px; left: -128px; top: -128px;\"></canvas></ymaps></ymaps><ymaps class=\"ymaps-2-1-73-copyrights-pane\" style=\"height: 0px; bottom: 0px; right: 0px; top: auto; left: 0px; position: absolute; z-index: 7002; margin-bottom: 0px;\"><ymaps><ymaps class=\"ymaps-2-1-73-copyright ymaps-2-1-73-copyright_logo_no\" style=\"\"><ymaps class=\"ymaps-2-1-73-copyright__fog\">…</ymaps><ymaps class=\"ymaps-2-1-73-copyright__wrap\"><ymaps class=\"ymaps-2-1-73-copyright__layout\"><ymaps class=\"ymaps-2-1-73-copyright__content-cell\"><ymaps class=\"ymaps-2-1-73-copyright__content\"><ymaps class=\"ymaps-2-1-73-copyright__text\">© Яндекс</ymaps><ymaps class=\"ymaps-2-1-73-copyright__agreeme